package com.oyuki.marketsquare.entity; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; @Entity @Table(name="procurement_items") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class ProcurementItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="procurement_id") private ProcurementRequest procurement; @Column(nullable=false) private String productName; @Column(nullable=false) private BigDecimal requestedQuantity; private String measurementUnit; private BigDecimal actualQuantity; private BigDecimal actualPrice; private String sellerName; private String notes; }